-- interview-batch4-diagrams.sql — 面試題庫補圖 批次 4
-- q3   兩級 NMOS 反相器（BSS138）：A=5V -> B=0V -> C=5V，ID(R452)=1.2mA
-- q8   SPI 串聯端接：Master 輸出的三條線在 Master 側串 22-33R，MISO 串在 Slave 側
-- q9   同步 vs 非同步 Buck：下管 FET vs 蕭特基（答案是同步）
-- q10  上管 OFF 的續流路徑：迴路經 body diode 與 L，不經 HS
-- q11  RC Snubber：串聯 RC 跨接 D-S，附振鈴 vs 阻尼波形對照
--
-- 兩道驗證都過：瀏覽器重疊實測 = 0；語意/幾何斷言全過（續流迴路封閉且避開 HS、
--   二極體陰極朝 SW、箭頭方向 3 右 1 左、振鈴曲線穿越穩態值 6 次而阻尼曲線 0 次過衝）
-- 用法：Supabase Dashboard → SQL Editor → 全部貼上 → Run。冪等，可重跑。

-- q3：兩級 NMOS 反相器，標出 A/B/C 位準
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then n.box || answer else answer end,
  answer_en = case when answer_en is not null and answer_en not like '%<svg%' then n.box || answer_en else answer_en end,
  answer_ja = case when answer_ja is not null and answer_ja not like '%<svg%' then n.box || answer_ja else answer_ja end,
  answer_ko = case when answer_ko is not null and answer_ko not like '%<svg%' then n.box || answer_ko else answer_ko end
  from (select $vsq$<div class="exam-diagram-box"><svg width="520" height="300" viewBox="0 0 520 300" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="300" fill="#ffffff"/><text x="260" y="20" fill="#1d2943" font-size="13" text-anchor="middle" font-weight="bold">BSS138 two-stage inverter: A HIGH -> B LOW -> C HIGH</text><text x="14" y="174" fill="#15803d" font-size="11" font-weight="bold">A = 5V</text><line x1="60" y1="170" x2="66" y2="170" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="resistor"><line x1="66" y1="170" x2="78" y2="170" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><polyline points="78,170 81,163 87,177 93,163 99,177 102,170" fill="none" stroke="#1f4fd1" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><line x1="102" y1="170" x2="114" y2="170" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="90" y="150" fill="#1d2943" font-size="11" text-anchor="middle">R1</text><text x="90" y="196" fill="#64748b" font-size="11" text-anchor="middle">10k</text><line x1="114" y1="170" x2="120" y2="170" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="rail"><line x1="230" y1="52" x2="230" y2="64" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="222" y1="52" x2="238" y2="52" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="244" y="58" fill="#b91c1c" font-size="11" font-weight="bold">12V</text><g data-sym="resistor"><line x1="230" y1="76" x2="230" y2="88" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><polyline points="230,88 223,91 237,97 223,103 237,109 230,112" fill="none" stroke="#1f4fd1" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><line x1="230" y1="112" x2="230" y2="124" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="244" y="96" fill="#1d2943" font-size="11">R452</text><text x="244" y="112" fill="#64748b" font-size="11">10k</text><line x1="230" y1="64" x2="230" y2=