"2" stroke-linecap="round"/></g><text x="120" y="206" fill="#1d2943" font-size="11" text-anchor="end" font-weight="bold">Q27</text><line x1="176" y1="190" x2="176" y2="214" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="ground"><line x1="176" y1="214" x2="176" y2="228" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="164" y1="228" x2="188" y2="228" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="168" y1="233" x2="184" y2="233" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="172" y1="238" x2="180" y2="238" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><polyline points="230,150 300,150 300,170 340,170" fill="none" stroke="#1f4fd1" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><g data-sym="rail"><line x1="450" y1="52" x2="450" y2="64" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="442" y1="52" x2="458" y2="52" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="464" y="58" fill="#b91c1c" font-size="11" font-weight="bold">5V</text><g data-sym="resistor"><line x1="450" y1="76" x2="450" y2="88" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><polyline points="450,88 443,91 457,97 443,103 457,109 450,112" fill="none" stroke="#1f4fd1" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><line x1="450" y1="112" x2="450" y2="124" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="464" y="96" fill="#1d2943" font-size="11">R453</text><text x="464" y="112" fill="#64748b" font-size="11">10k</text><line x1="450" y1="64" x2="450" y2="76" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="450" y1="124" x2="450" y2="150" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="396" y1="150" x2="450" y2="150" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="junction"><circle cx="450" cy="150" r="2.6" fill="#1f4fd1"/></g><text x="460" y="140" fill="#15803d" font-size="11" font-weight="bold">C = 5V</text><g data-sym="nmos"><line x1="340" y1="170" x2="354" y2="170" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="354" y1="158" x2="354" y2="182" stroke="#1f4fd1" stroke-width="2.6" stroke-linecap="round"/><line x1="361" y1="157" x2="361" y2="183" stroke="#1f4fd1" stroke-width="2.6" stroke-linecap="round"/><line x1="361" y1="162" x2="374" y2="162" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="374" y1="162" x2="374" y2="150" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="374" y1="150" x2="396" y2="150" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="361" y1="178" x2="374" y2="178" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="374" y1="178" x2="374" y2="190" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="374" y1="190" x2="396" y2="190" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="361" y1="170" x2="374" y2="170" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><polygon points="367,166 367,174 361,170" fill="#1f4fd1" stroke="#1f4fd1" stroke-width="1"/><line x1="374" y1="170" x2="374" y2="178" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="388" y1="190" x2="388" y2="176" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><polygon points="382,176 394,176 388,164" fill="none" stroke="#1f4fd1" stroke-width="2"/><line x1="382" y1="164" x2="394" y2="164" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="388" y1="164" x2="388" y2="150" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="340" y="206" fill="#1d2943" font-size="11" text-anchor="end" font-weight="bold">Q28</text><line x1="396" y1="190" x2="396" y2="214" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="ground"><line x1="396" y1="214" x2="396" y2="228" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="384" y1="228" x2="408" y2="228" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="388" y1="233" x2="404" y2="233" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="392" y1="238" x2="400" y2="238" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="10" y="272" fill="#1d2943" font-size="11">Q27 on: B is pulled to GND. ID = 12V / 10k = 1.2mA</text><text x="10" y="292" fill="#64748b" font-size="11">Q28 off: no current in R453, so C sits at 5V. BSS138 VTH = 1.5V typ.</text></svg></div>$vsq$ as box) n
 where question like $q$%BSS138 NMOS 電路分析%$q$;

-- q8：SPI 串聯端接電阻放源端
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then n.box || answer else answer end,
  answer_en = case when answer_en is not null and answer_en not like '%<svg%' then n.box || answer_en else answer_en end,
  answer_ja = case when answer_ja is not null and answer_ja not like '%<svg%' then n.box || answer_ja else answer_ja end,
  answer_ko = case when answer_ko is not null and answer_ko not like '%<svg%' then n.box || answer_ko else answer_ko end
  from (select $vsq$<div class="exam-diagram-box"><svg width="520" height="330" viewBox="0 0 520 330" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="330" fill="#ffffff"/><text x="260" y="20" fill="#1d2943" font-size="13" text-anchor="middle" font-weight="bold">SPI series resistor: it belongs at the driver</text><text x="260" y="46" fill="#64748b" font-size="12" text-anchor="middle">22-33 ohm, one per line, close to the source</text><g data-sym="ic"><rect x="30" y="102" width="80" height="150" rx="3" fill="#fff" stroke="#1f4fd1" stroke-width="2"/></g><text x="70" y="170" fill="#1d2943" font-size="11" text-anchor="middle" font-weight="bold">Master</text><text x="70" y="188" fill="#64748b" font-size="11" text-anchor="middle">driver</text><g data-sym="ic"><rect x="415" y="102" width="80" height="150" rx="3" fill="#fff" stroke="#1f4fd1" stroke-width="2"/></g><text x="455" y="170" fill="#1d2943" font-size="11" text-anchor="middle" font-weight="bold">Slave</text><text x="455" y="188" fill="#64748b" font-size="11" text-anchor="middle">flash</text><line x1="110" y1="120" x2="146" y2="120" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="resistor"><line x1="146" y1="120" x2="158" y2="120" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><polyline points="158,120 161,113 167,127 173,113 179,127 182,120" fill="none" stroke="#1f4fd1" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><line x1="182" y1="120" x2="194" y2="120" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><line x1="194" y1="120" x2="415" y2="120" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><text x="300" y="110" fill="#1d2943" font-size="11" text-anchor="middle">SCLK</text><polygon points="264,116 264,124 272,120" fill="#1f4fd1" stroke="#1f4fd1" stroke-width="1"/><line x1="110" y1="158" x2="146" y2="158" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="resistor"><line x1="146" y1="158" x2="158" y2="158" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><polyline points="158,158 161,151 167,165 173,151 179,165 182,158" fill="none" stroke="#1f4fd1" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><line x1="182" y1="158" x2="194" y2="158" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><line x1="194" y1="158" x2="415" y2="158" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><text x="300" y="148" fill="#1d2943" font-size="11" text-anchor="middle">MOSI</text><polygon points="264,154 264,162 272,158" fill="#1f4fd1" stroke="#1f4fd1" stroke-width="1"/><line x1="110" y1="234" x2="146" y2="234" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="resistor"><line x1="146" y1="234" x2="158" y2="234" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><polyline points="158,234 161,227 167,241 173,227 179,241 182,234" fill="none" stroke="#1f4fd1" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><line x1="182" y1="234" x2="194" y2="234" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><line x1="194" y1="234" x2="415" y2="234" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><text x="300" y="224" fill="#1d2943" font-size="11" text-anchor="middle">CS#</text><polygon points="264,230 264,238 272,234" fill="#1f4fd1" stroke="#1f4fd1" stroke-width="1"/><line x1="110" y1="196" x2="331" y2="196" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="resistor"><line x1="331" y1="196" x2="343" y2="196" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><polyline points="343,196 346,189 352,203 358,189 364,203 367,196" fill="none" stroke="#1f4fd1" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><line x1="367" y1="196" x2="379" y2="196" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><line x1="379" y1="196" x2="415" y2="196" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><text x="250" y="186" fill="#1d2943" font-size="11" text-anchor="middle">MISO</text><polygon points="276,192 276,200 268,196" fill="#1f4fd1" stroke="#1f4fd1" stroke-width="1"/><text x="200" y="94" fill="#b45309" font-size="11">R at the driver end, not the far end</text><text x="140" y="220" fill="#b45309" font-size="11">MISO source is the slave</text><text x="10" y="290" fill="#1d2943" font-size="11">R + Rout ~ Z0 at the driver, so the reflected edge dies where it started.</text><text x="10" y="310" fill="#64748b" font-size="11">SCLK, MOSI and CS# are master-driven; MISO is not - its resistor sits at the slave.</text></svg></div>$vsq$ as box) n
 where question like $q$%SPI 線路設計時常會串一個電阻%$q$;

