troke-linecap="round"/><line x1="292" y1="230" x2="292" y2="250" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><text x="304" y="210" fill="#64748b" font-size="11">Load</text><g data-sym="ground"><line x1="292" y1="250" x2="292" y2="264" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="280" y1="264" x2="304" y2="264" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="284" y1="269" x2="300" y2="269" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="288" y1="274" x2="296" y2="274" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><g data-sym="ground"><line x1="196" y1="250" x2="196" y2="264" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="184" y1="264" x2="208" y2="264" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="188" y1="269" x2="204" y2="269" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="192" y1="274" x2="200" y2="274" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="134" y="128" fill="#b91c1c" font-size="11" text-anchor="end" font-weight="bold">OFF</text><text x="346" y="120" fill="#1d2943" font-size="11">iL cannot stop instantly:</text><text x="346" y="140" fill="#1d2943" font-size="11">V = L x di/dt would spike.</text><text x="346" y="168" fill="#15803d" font-size="11">The LS body diode (drawn</text><text x="346" y="188" fill="#15803d" font-size="11">inside the FET) takes it</text><text x="346" y="208" fill="#15803d" font-size="11">during dead time.</text><text x="10" y="296" fill="#1d2943" font-size="11">Sync buck: that path is the LS body diode, VF ~0.7V - lossy, so keep dead time short.</text><text x="10" y="316" fill="#64748b" font-size="11">Non-sync buck: a real Schottky does the same job at VF ~0.3V.</text></svg></div>$vsq$ as box) n
 where question like $q$%Buck 電路中的%$q$;

-- q11：RC Snubber 與振鈴抑制
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then n.box || answer else answer end,
  answer_en = case when answer_en is not null and answer_en not like '%<svg%' then n.box || answer_en else answer_en end,
  answer_ja = case when answer_ja is not null and answer_ja not like '%<svg%' then n.box || answer_ja else answer_ja end,
  answer_ko = case when answer_ko is not null and answer_ko not like '%<svg%' then n.box || answer_ko else answer_ko end
  from (select $vsq$<div class="exam-diagram-box"><svg width="520" height="340" viewBox="0 0 520 340" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="340" fill="#ffffff"/><text x="260" y="20" fill="#1d2943" font-size="13" text-anchor="middle" font-weight="bold">RC snubber: what SR2 + SC3 actually do</text><g data-sym="rail"><line x1="40" y1="66" x2="40" y2="78" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="32" y1="66" x2="48" y2="66" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="40" y="58" fill="#b91c1c" font-size="11" text-anchor="middle" font-weight="bold">VIN</text><line x1="40" y1="78" x2="40" y2="84" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="40" y1="84" x2="70" y2="84" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="inductor"><line x1="70" y1="84" x2="76" y2="84" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><path d="M 76 84 A 4.5 4.5 0 1 1 85 84 A 4.5 4.5 0 1 1 94 84 A 4.5 4.5 0 1 1 103 84 A 4.5 4.5 0 1 1 112 84" fill="none" stroke="#1f4fd1" stroke-width="2"/><line x1="112" y1="84" x2="118" y2="84" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="94" y="70" fill="#64748b" font-size="11" text-anchor="middle">Lstray</text><line x1="118" y1="84" x2="150" y2="84" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="150" y1="84" x2="150" y2="140" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="junction"><circle cx="150" cy="104" r="2.6" fill="#1f4fd1"/></g><g data-sym="nmos"><line x1="94" y1="160" x2="108" y2="160" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="108" y1="148" x2="108" y2="172" stroke="#1f4fd1" stroke-width="2.6" stroke-linecap="round"/><line x1="115" y1="147" x2="115" y2="173" stroke="#1f4fd1" stroke-width="2.6" stroke-linecap="round"/><line x1="115" y1="152" x2="128" y2="152" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="128" y1="152" x2="128" y2="140" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="128" y1="140" x2="150" y2="140" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="115" y1="168" x2="128" y2="168" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="128" y1="168" x2="128" y2="180" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="128" y1="180" x2="150" y2="180" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="115" y1="160" x2="128" y2="160" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><polygon points="121,156 121,164 115,160" fill="#1f4fd1" stroke="#1f4fd1" stroke-width="1"/><line x1="128" y1="160" x2="128" y2="168" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="142" y1="180" x2="142" y2="166" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><polygon points="136,166 148,166 142,154" fill="none" stroke="#1f4fd1" stroke-width="2"/><line x1="136" y1="154" x2="148" y2="154" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="142" y1="154" x2="142" y2="140" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="120" y="206" fill="#1d2943" font-size="11" text-anchor="middle">Q1</text><line x1="94" y1="160" x2="50" y2="160" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><text x="44" y="164" fill="#1d2943" font-size="11" text-anchor="end" font-weight="bold">PWM</text><line x1="150" y1="180" x2="150" y2="240" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="junction"><circle cx="150" cy="206" r="2.6" fill="#1f4fd1"/></g><g data-sym="ground"><line x1="150" y1="240" x2="150" y2="254" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="138" y1="254" x2="162" y2="254" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="142" y1="259" x2="158" y2="259" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="146" y1="264" x2="154" y2="264" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><line x1="150" y1="104" x2="215" y2="104" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="resistor"><line x1="215" y1="108" x2="215" y2="120" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><polyline points="215,120 208,123 222,129 208,135 222,141 215,144" fill="none" stroke="#1f4fd1" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><line x1="215" y1="144" x2="215" y2="156" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><line x1="215" y1="104" x2="215" y2="108" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="215" y1="156" x2="215" y2="162" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="capacitor"><line x1="215" y1="162" x2="215" y2="179" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="204" y1="179" x2="226" y2="179" stroke="#1f4fd1" stroke-width="2.6" stroke-linecap="round"/><line x1="204" y1="189" x2="226" y2="189" stroke="#1f4fd1" stroke-width="2.6" stroke-linecap="round"/><line x1="215" y1="189" x2="215" y2="206" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><line x1="215" y1="206" x2="150" y2="206" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><text x="227" y="128" fill="#1d2943" font-size="11" font-weight="bold">SR2</text><text x="227" y="144" fill="#64748b" font-size="11">1-10 ohm</text><text x="227" y="180" fill="#1d2943" font-size="11" font-weight="bold">SC3</text><text x="227" y="196" fill="#64748b" font-size="11">100p-1n</text><line x1="284" y1="60" x2="284" y2="260" stroke="#cbd5e1" stroke-width="1" stroke-linecap="round"/><line x1="300" y1="76" x2="300" y2="200" stroke="#94a3b8" stroke-width="1.4" stroke-linecap="round"/><line x1="300" y1="200" x2="505" y2="200" stroke="#94a3b8" stroke-width="1.4" stroke-linecap="round"/><text x="304" y="72" fill="#64748b" font-size="11">VDS</text><line x1="300" y1="92" x2="500" y2="92" stroke="#b91c1c" stroke-width="1.2