e" stroke="#15803d" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><text x="300" y="222" fill="#b91c1c" font-size="11">no snubber: spike + ringing</text><text x="300" y="240" fill="#15803d" font-size="11">with RC snubber: damped</text><text x="10" y="300" fill="#1d2943" font-size="11">Snubber = R + C across drain-source: C takes the Lstray spike, R burns the ring.</text><text x="10" y="320" fill="#64748b" font-size="11">R ~ sqrt(Lstray/Coss), C > 2 x Coss, mounted at the FET pins or it adds its own L.</text></svg></div>$vsq$ as box) n
 where question like $q$%SR2, SC3 組成的電路%$q$;

-- 驗收：七列的 zh / en 都要 t
select left(question, 22) as q,
       answer like '%<svg%' as zh, answer_en like '%<svg%' as en,
       answer_ja like '%<svg%' as ja, answer_ko like '%<svg%' as ko
  from public.interview_questions
 where question like $q$%BSS138 NMOS 電路分析%$q$
    or question like $q$%SPI 線路設計時常會串一個電阻%$q$
    or question like $q$%若下管為%$q$
    or question like $q$%Buck 電路中的%$q$
    or question like $q$%SR2, SC3 組成的電路%$q$;
